    },
    {
      "indicator": "MM20",
      "reading": "11.1045",
      "interpretation": "MM20 = 11,1045; leve inclinação negativa (~-0,028 R$/dia nos últimos 20 pregões). Atua como suporte próximo."
    },
    {
      "indicator": "MM50",
      "reading": "11.3878",
      "interpretation": "MM50 = 11,3878; preço abaixo da MM50 -> resistência relevante; MM50 ainda > MM200, mas está achatada."
    },
    {
      "indicator": "MM200",
      "reading": "9.6900",
      "interpretation": "MM200 = 9,6900; preço bem acima — tendência de longo prazo de alta intacta."
    },
    {
      "indicator": "EMA9",
      "reading": "11.0497",
      "interpretation": "EMA9 = 11,0497; abaixo da EMA21 (11,1308) — curto prazo com leve fraqueza; preço acima da EMA9."
    },
    {
      "indicator": "EMA21",
      "reading": "11.1308",
      "interpretation": "EMA21 = 11,1308; próximo ao preço — confirma zona neutra no curto prazo."
    },
